=== README.md
# weather

Forecast client. `fake_api.py` is a local stand-in for the forecast API that checks the API key the
way the real one does, so you can run the client offline: `python3 -c "import client; print(client.forecast('Montreal'))"`.
The key lives in `.env`. Run the tests with `python3 -m unittest`.

=== client.py
"""Forecast client."""
import os

import env
import fake_api

env.load()


class ForecastError(Exception):
    pass


def headers():
    key = os.environ["WEATHER_API_KEY"]
    return {"Authorization": f"Bearer{key}", "Accept": "application/json"}


def forecast(city, transport=fake_api):
    status, body = transport.get(f"/v1/forecast/{city}", headers())
    if status != 200:
        raise ForecastError(f"{status} {body.get('error')}")
    return body

=== env.py
import os


def load(path=".env"):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line and not line.startswith("#") and "=" in line:
                k, v = line.split("=", 1)
                os.environ.setdefault(k, v)

